mapper.select:
SELECT COALESCE(MAX(version_no), 0) + 1
FROM policy_document_version
WHERE policy_document_id = #{policyDocumentId}

SELECT EXISTS (
    SELECT 1
    FROM policy_document_version version
    JOIN policy_document document
      ON document.policy_document_id = version.policy_document_id
    WHERE version.policy_document_version_id =
          #{policyDocumentVersionId}
      AND document.is_active = 1
      AND version.published_dttm <= #{currentDttm}
      AND version.effective_from_dttm <= #{currentDttm}
)

SELECT EXISTS (
    SELECT 1
    FROM policy_document_version version
    JOIN policy_document document
      ON document.policy_document_id = version.policy_document_id
    WHERE version.policy_document_version_id =
          #{policyDocumentVersionId}
      AND document.policy_type_code = #{policyType}
      AND document.is_active = 1
      AND version.published_dttm <= #{currentDttm}
      AND version.effective_from_dttm <= #{currentDttm}
)

mapper.insert:
INSERT INTO policy_document (
    policy_type_code, title, audience_code, is_active
) VALUES (
    #{policyType}, #{title}, #{audience}, #{active}
)

mapper.update:
UPDATE policy_document
SET is_active = #{active}
WHERE policy_document_id = #{policyDocumentId}

mapper.insert:
INSERT INTO policy_document_version (
    policy_document_id, version_no, body,
    published_dttm, published_by_member_id,
    effective_from_dttm, is_required
) VALUES (
    #{policyDocumentId}, #{versionNo}, #{body},
    #{publishedDttm}, #{publishedByMemberId},
    #{effectiveFromDttm}, #{required}
)
